// DecodeStrategyPausedEvent decodes a "StrategyPaused(uint8,uint64)" log.
func (c *IDiesisCoreVaultBinding) DecodeStrategyPausedEvent(log types.Log) (out IDiesisCoreVaultStrategyPausedEvent, err error) {
	defer func() {
		if failure := recover(); failure != nil {
			err = fmt.Errorf("invalid ABI event: %v", failure)
		}
	}()
	definition, err := c.event("StrategyPaused(uint8,uint64)")
	if err != nil {
		return out, err
	}
	if len(log.Topics) == 0 || log.Topics[0] != definition.ID {
		return out, fmt.Errorf("event signature mismatch for %s", "StrategyPaused(uint8,uint64)")
	}
	if len(log.Topics) != 2 {
		return out, fmt.Errorf("event topic count mismatch for %s", "StrategyPaused(uint8,uint64)")
	}
	if len(definition.Inputs.NonIndexed()) > 0 {
		values, err := definition.Inputs.NonIndexed().Unpack(log.Data)
		if err != nil {
			return out, err
		}
		if len(values) != 1 {
			return out, fmt.Errorf("event value count mismatch")
		}
		out.ExpiresAtBlock = *abi.ConvertType(values[0], new(uint64)).(*uint64)
	} else if len(log.Data) != 0 {
		return out, fmt.Errorf("unexpected event data")
	}
	var indexed abi.Arguments
	var indexedTopics []common.Hash
	indexed = append(indexed, definition.Inputs[0])
	indexedTopics = append(indexedTopics, log.Topics[1])
	if err := abi.ParseTopics(&out, indexed, indexedTopics); err != nil {
		return out, err
	}
	return out, nil
}

